import os
import time

from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.vdu.utilities.file_operations import unzip_file_with_cleanup
from taf.gnb.oam.coam.vdu.services.swm.http_client_v1 import SWMv1HttpClient

from taf.gnb.oam.coam.vdu.exceptions import ApiException


@auto_token_refresh()
class SWMv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = SWMv1HttpClient(base_url=con_details.base_url, connection_alias=con_details.alias)

    def trigger_sw_update(self, file_path, xml_file_name='TargetBD_EXD.xml', sw_update_type='ALD', sw_update_source='WEBEM',
                          timeout=30, operation_timeout=300):
        """
        Trigger a software update process, handling both zipped and unzipped files.
        If the file is a zip, it will be unzipped and cleaned up after use.
        """
        if ".zip" in file_path:
            with unzip_file_with_cleanup(file_path) as extracted_path:
                self._trigger_sw_update(file_path=extracted_path,
                                        xml_file_name=xml_file_name,
                                        sw_update_type=sw_update_type,
                                        sw_update_source=sw_update_source,
                                        timeout=timeout,
                                        operation_timeout=operation_timeout)
        else:
            self._trigger_sw_update(file_path=file_path,
                                    xml_file_name=xml_file_name,
                                    sw_update_type=sw_update_type,
                                    sw_update_source=sw_update_source,
                                    timeout=timeout,
                                    operation_timeout=operation_timeout)

    def _trigger_sw_update(self, file_path, xml_file_name, sw_update_type, sw_update_source, timeout, operation_timeout):
        stop_time = time.time() + operation_timeout
        trigger_operation_id = self.local_client.trigger_sw_update(sw_update_type=sw_update_type,
                                                                   sw_update_source=sw_update_source,
                                                                   target_bd_file_path=os.path.join(file_path, xml_file_name),
                                                                   target_bd_file_name=xml_file_name,
                                                                   timeout=timeout)["id"]

        posted_files = []
        while time.time() < stop_time:
            status = self.local_client.get_sw_update_operation_status(operation_id=trigger_operation_id,
                                                                      timeout=timeout)["status"]

            if status == "success":
                self._teardown_sw_update(operation_id=trigger_operation_id, timeout=timeout)
                return

            elif status == "ongoing":
                self._post_sw_update_files(operation_id=trigger_operation_id,
                                           file_path=file_path,
                                           timeout=timeout,
                                           posted_files=posted_files)

            elif status == "failure":
                self._teardown_sw_update(operation_id=trigger_operation_id, timeout=timeout)
                raise Exception("Trigger SW update operation failed")

            time.sleep(3)

        self._teardown_sw_update(operation_id=trigger_operation_id, timeout=timeout)
        raise Exception(f"SW update operation timed out, timeout {operation_timeout}s exceeded.")

    def _post_sw_update_files(self, operation_id, file_path, timeout, posted_files):
        try:
            file_list = self.local_client.get_sw_update_file_list(operation_id=operation_id, timeout=timeout)["fileList"]

            for file_name in file_list:
                if file_name not in posted_files:
                    self.local_client.post_sw_update_file(
                        operation_id=operation_id,
                        file_name=file_name,
                        file_path=os.path.join(file_path, file_name),
                        total_files=str(len(file_list)),
                        file_number=str(file_list.index(file_name) + 1),
                        timeout=timeout
                    )

                    posted_files.append(file_name)

        except Exception as e:
            self._teardown_sw_update(operation_id=operation_id, timeout=timeout)
            raise e

    def _teardown_sw_update(self, operation_id, timeout):
        try:
            self.local_client.delete_sw_update_operation(operation_id=operation_id, timeout=timeout)
            self.local_client.delete_sw_update_file_operation(operation_id=operation_id, timeout=timeout)
        except ApiException:
            pass
